          });

          if (savedAuraId) {
            setAuraId(savedAuraId);
            setShowShareButton(true);
            console.log("Varsayılan aura verileri kaydedildi");
          }
        } catch (err) {
          console.error("Aura kaydedilirken hata:", err);
        }

        // İlerlemeyi tamamla
        setLoadingProgress(100);

